74	    /**
75	     * The request header carrying a client-supplied idempotency token for owner creation. When a
76	     * create repeats with a token already seen, the originally created owner is returned with 200
77	     * instead of creating a duplicate.
78	     */
79	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
80	
81	    /**
82	     * Remembers, per idempotency key, the id of the owner created by the first request that carried
83	     * that key, so a repeat with the same key resolves back to the original owner instead of
84	     * creating a duplicate.
85	     */
86	    private final java.util.Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
