245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
248	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
249	        if (currentOwner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        currentOwner.setAddress(ownerFieldsDto.getAddress());
253	        currentOwner.setCity(ownerFieldsDto.getCity());
254	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
255	        currentOwner.setLastName(ownerFieldsDto.getLastName());
256	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
257	        this.clinicService.saveOwner(currentOwner);
258	        OwnerDto ownerDto = ownerMapper.toOwnerDto(currentOwner);
259	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
260	        return new ResponseEntity<>(ownerDto, HttpStatus.NO_CONTENT);
261	    }
