263	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
264	    @Transactional
265	    @Override
266	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner == null) {
269	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	        }
271	        // Soft delete: retain the row, flag it deleted. The owner remains readable via GET, but
272	        // duplicate/identity detection on create ignores owners flagged deleted.
273	        owner.setDeleted(true);
274	        this.clinicService.saveOwner(owner);
275	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
276	    }
