343	    private static boolean isBlank(String value) {
344	        return value == null || value.isBlank();
345	    }
346	
347	    /**
348	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when the
349	     * header is absent, blank, or there is no bound request. A present, non-blank value is trimmed.
350	     *
351	     * @return the trimmed idempotency key, or {@code null} when none was supplied
352	     */
353	    private static String currentIdempotencyKey() {
354	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
355	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
356	            return null;
357	        }
358	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
359	        return isBlank(key) ? null : key.trim();
360	    }
