362	    /**
363	     * The set of disposable email domains that owners may not register with. Compared
364	     * case-insensitively against the domain part of the supplied email.
365	     */
366	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
367	        "mailinator.com", "tempmail.com", "guerrillamail.com");
368	
369	    /**
370	     * Rejects an owner whose email domain is on the disposable-domain blocklist
371	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
372	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
373	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
374	     * case-insensitively; the stored email is already lower-cased.
375	     *
376	     * @param email the owner's email (may be {@code null})
377	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
378	     */
379	    private static void validateEmailDomain(String email) {
380	        if (isBlank(email)) {
381	            return;
382	        }
383	        int at = email.lastIndexOf('@');
384	        if (at < 0) {
385	            return;
386	        }
387	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
388	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
389	            throw new DisposableEmailDomainException(email);
390	        }
391	    }
392	
393	    /**
394	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
395	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
396	     */
397	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
398	        "NSW", new int[] {2000, 2099},
399	        "VIC", new int[] {3000, 3099},
400	        "QLD", new int[] {4000, 4099});
401	
402	    /**
403	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
404	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
405	     * present, the value has already passed the 4-digit format check (Bean Validation on the
406	     * request body); this enforces that it falls within the inclusive range for the city's region
407	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
408	     *
409	     * @param postcode the supplied postcode (may be {@code null})
410	     * @param region the owner's locality/region derived from its city
411	     * @throws InvalidPostcodeException if the postcode is out of range for the region
412	     */
413	    private static void validatePostcode(String postcode, String region) {
414	        if (isBlank(postcode)) {
415	            return;
416	        }
417	        int[] range = REGION_POSTCODES.get(region);
418	        if (range == null) {
419	            return;
420	        }
421	        int value;
422	        try {
423	            value = Integer.parseInt(postcode);
424	        }
425	        catch (NumberFormatException e) {
426	            throw new InvalidPostcodeException(postcode);
427	        }
428	        if (value < range[0] || value > range[1]) {
429	            throw new InvalidPostcodeException(postcode);
430	        }
431	    }
